mapper.sql:
where 1=1

		and crmp_llave = #{key}


		and crmp_estado = #{state}


		and crmp_cuenta = #{account}


		and crmp_periodo = #{timeFrame}


		and nrmp_cantidad = #{quantity}


		and mrmp_saldoanterior = #{lastBalance}


		and mrmp_positivo = #{positive}


		and mrmp_negativo = #{negative}


		and mrmp_valor = #{value}

mapper.select:
select ${level} as key
	,(select min(dptm_fechainicio) from account.periodotiempo_ptm where nptm_nivel = ${level}) as startDate
	,(select max(dptm_fechafin) from account.periodotiempo_ptm where nptm_nivel = ${level}) as endDate;
